8	import java.util.List;
9	
10	/**
11	 * 自动暂停记录数据访问。唯一约束 uk_pause_release_round 保证每轮至多一条，历史只增不改。
12	 */
13	@Repository
14	public class PauseRecordRepository {
15	
16	    private static final RowMapper<PauseRecord> MAPPER = (rs, rowNum) -> new PauseRecord(
17	            rs.getLong("id"), rs.getLong("release_id"), rs.getInt("monitor_round"),
18	            rs.getLong("trigger_task_id"), rs.getInt("success_count"), rs.getInt("failed_count"),
19	            rs.getString("paused_at_utc"));
20	
21	    private static final String COLUMNS = "id, release_id, monitor_round, trigger_task_id,"
22	            + " success_count, failed_count, paused_at_utc";
23	
24	    private final JdbcTemplate jdbc;
25	
26	    public PauseRecordRepository(JdbcTemplate jdbc) {
27	        this.jdbc = jdbc;
28	    }
29	
30	    public void insert(long releaseId, int monitorRound, long triggerTaskId,
31	                       int successCount, int failedCount, String pausedAtUtc) {
32	        jdbc.update("INSERT INTO release_pause_record"
33	                        + " (release_id, monitor_round, trigger_task_id, success_count, failed_count, paused_at_utc)"
34	                        + " VALUES (?, ?, ?, ?, ?, ?)",
35	                releaseId, monitorRound, triggerTaskId, successCount, failedCount, pausedAtUtc);
36	    }
37	
38	    public List<PauseRecord> findByRelease(long releaseId) {
39	        return jdbc.query("SELECT " + COLUMNS + " FROM release_pause_record WHERE release_id = ? ORDER BY id",
40	                MAPPER, releaseId);
41	    }
42	
43	    public long countByRelease(long releaseId) {
44	        Long count = jdbc.queryForObject(
45	                "SELECT COUNT(*) FROM release_pause_record WHERE release_id = ?", Long.class, releaseId);
