/**
 * 发布启动冻结预校验：命中生效窗口内的冻结范围时，必须携带完整紧急例外，否则 422。
 */
public void assertReleaseStartAllowed(String model, EmergencyException exception) {
    Instant now = Instant.now(clock);
    List<FreezeOrder> hits = matchingActiveFreezes(model, null, now);
    if (hits.isEmpty()) {
        return;
    }
    EmergencyException valid = requireValidException(exception);
    recordExceptionUse("release.create", "release:new", valid);
}

/**
 * 新任务拉取冻结预校验：与发布启动同一裁决规则。调用方须先持有冻结裁决行锁。
 */
public void assertPullAllowed(String model, long releaseId, EmergencyException exception) {
    Instant now = Instant.now(clock);
    List<FreezeOrder> hits = matchingActiveFreezes(model, releaseId, now);
    if (hits.isEmpty()) {
        return;
    }
    EmergencyException valid = requireValidException(exception);
    recordExceptionUse("task.pull", "device:" + model, valid);
}

